function fieldHTML(f){const attrs=`name="${esc(f.name)}" id="field-${esc(f.name)}"`;return `<div class="field ${f.span?'span-2':''}"><label for="field-${esc(f.name)}">${esc(f.label)}</label>${f.type==='select'?`<select ${attrs}>${f.options.map(o=>`<option value="${esc(o.value)}" ${String(f.value)===String(o.value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea ${attrs} placeholder="${esc(f.placeholder||'')}">${esc(f.value)}</textarea>`:`<input ${attrs} inputmode="decimal" type="number" step="${esc(f.step||'any')}" value="${esc(f.value)}" required />`}${f.hint?`<small>${esc(f.hint)}</small>`:''}</div>`}
function renderTool(id){const t=byId[id];if(!t){setBreadcrumb('Não encontrado');main.innerHTML=`<div class="not-found"><h2>Ferramenta não encontrada</h2><p>Esta página não existe.</p><button class="primary-button" data-nav="home">Voltar ao início</button></div>`;return}setBreadcrumb(t.name);lastResult=null;
 const fav=state.favorites.includes(id);
 main.innerHTML=`<div class="tool-header"><div class="tool-title-wrap">${catIcon(t)}<div><div class="eyebrow" style="margin-bottom:5px">${esc(t.cat.toUpperCase())}</div><h1>${esc(t.name)}</h1><p>${esc(t.desc)}</p></div></div><div class="tool-actions"><button class="ghost-button" data-favorite="${id}" aria-label="${fav?'Remover dos favoritos':'Adicionar aos favoritos'}">${icon('star')} <span>${fav?'Favorito':'Favoritar'}</span></button><button class="ghost-button" id="tool-help">${icon('circle-help')} <span>Ajuda</span></button></div></div>`;
 document.querySelector('#tool-help').addEventListener('click',showHelp);
 if(id==='calculadora'||id==='cientifica'){renderCalculator(id);return}
 const fields=getFields(id),form=`<div class="panel"><div class="panel-heading"><h2>Configure seu cálculo</h2><span>${icon('settings')}</span></div><form id="tool-form" novalidate><div class="field-grid" id="field-grid">${fields.map(fieldHTML).join('')}</div><div class="panel-actions"><button type="submit" class="primary-button">${icon('calculator')} Calcular agora ${icon('arrow-right')}</button><button type="button" id="reset-form" class="ghost-button">${icon('rotate-ccw')} Restaurar</button></div></form><p class="helper-note">${icon('info')} Utilize ponto ou vírgula decimal no campo numérico conforme seu navegador.</p></div>`;
 main.insertAdjacentHTML('beforeend',`<div class="workspace-grid"><div>${form}</div><div class="panel result-panel" id="result-panel"><div class="panel-heading"><h2>Seu resultado</h2><span>${icon('sparkles')}</span></div><div class="result-empty"><span class="empty-icon">${icon('calculator')}</span><b>Pronto para calcular</b><p>Preencha os dados ao lado e veja o resultado com o passo a passo.</p></div></div></div><div id="chart-slot"></div><div class="subtle-banner"><strong>${icon('sparkles')} Aprenda enquanto calcula.</strong> Além do resultado, cada ferramenta apresenta os conceitos, fórmulas ou etapas utilizados. Seus resultados ficam salvos apenas neste dispositivo.</div>`);
 const formEl=document.querySelector('#tool-form');formEl.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(formEl));try{const result=evaluate(id,data);lastResult={id,result,data};presentResult(result);storage.addHistory({tool:id,summary:Object.entries(data).slice(0,3).map(([key,val])=>`${key}: ${val}`).join(' · '),result:String(result.value).slice(0,110)});storage.track(id)}catch(err){toast(err.message||'Não foi possível calcular.','error');document.querySelector('#result-panel').querySelector('.result-empty')?.remove()}});
 formEl.addEventListener('change',e=>{if(e.target.tagName!=='SELECT')return;const dynamic=['areas','perimetros','volumes','primos','conversores','porcentagem','regra3'];if(!dynamic.includes(id))return;const vals=Object.fromEntries(new FormData(formEl));const k=e.target.name;if(id==='conversores'&&k==='tipo'){delete vals.origem;delete vals.destino}if(id==='porcentagem'&&k==='modo')delete vals.taxa;if(['areas','perimetros','volumes'].includes(id)&&k==='figura'){const keep=vals.figura;Object.keys(vals).forEach(x=>{if(x!=='figura')delete vals[x]});vals.figura=keep}document.querySelector('#field-grid').innerHTML=getFields(id,vals).map(fieldHTML).join('')});
 document.querySelector('#reset-form').addEventListener('click',()=>{document.querySelector('#field-grid').innerHTML=getFields(id).map(fieldHTML).join('');document.querySelector('#result-panel').innerHTML=`<div class="panel-heading"><h2>Seu resultado</h2>${icon('sparkles')}</div><div class="result-empty"><span class="empty-icon">${icon('calculator')}</span><b>Pronto para calcular</b><p>Altere os valores e clique em calcular.</p></div>`;document.querySelector('#chart-slot').innerHTML='';lastResult=null;destroyCharts()});
}
function presentResult(result){const panel=document.querySelector('#result-panel');if(!panel)return;const visual=result.visual?`<div class="visualization">${result.visual}</div>`:'';
 const details=result.details?.length?`<div class="result-details">${result.details.map(([label,val])=>`<div class="detail-row"><span>${esc(label)}</span><strong>${esc(val)}</strong></div>`).join('')}</div>`:'';
 const steps=result.steps?.length?`<div class="steps"><h3>Passo a passo da resolução</h3><ol>${result.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`:'';
 const pills=result.pills?`<div class="data-pills scroll-pills">${result.pills.map(p=>`<span class="data-pill ${/^[0-9]+$/.test(String(p))?'prime':''}">${esc(p)}</span>`).join('')}</div>`:'';
 const rows=result.rows?`<div class="table-container"><table class="data-table"><thead><tr><th>Operação</th><th>Resultado</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${esc(r[0])}</td><td><strong>${esc(r[1])}</strong></td></tr>`).join('')}</tbody></table></div>`:'';
 const imc=result.imc!==undefined?`<div class="imc-track" aria-label="Faixas do índice de massa corporal"><i></i><i></i><i></i><i></i><span class="imc-marker" style="left:${Math.max(1,Math.min(99,(result.imc-13)/(45-13)*100))}%"></span></div><div class="imc-labels"><span>Baixo peso</span><span>Adequado</span><span>Sobrepeso</span><span>Obesidade</span></div><p class="helper-note">IMC é um indicador de triagem para adultos, não um diagnóstico médico.</p>`:'';
 panel.innerHTML=`<div class="panel-heading"><h2>Seu resultado</h2><span>${icon('check-circle')}</span></div><div class="result-output">${visual}<div class="result-label">${esc(result.label)}</div><div class="result-number gradient">${esc(result.value)}</div>${result.description?`<div class="result-description">${esc(result.description)}</div>`:''}${imc}${details}${pills}${rows}${steps}<div class="result-actions"><button class="ghost-button" id="copy-result">${icon('copy')} Copiar resultado</button>${result.exportable?`<button class="ghost-button" id="export-pdf">${icon('file-text')} Exportar PDF</button><button class="ghost-button" id="export-png">${icon('image')} Exportar imagem</button>`:''}</div></div>`;
 document.querySelector('#copy-result').addEventListener('click',()=>copyText(result.value));if(result.exportable){document.querySelector('#export-pdf').addEventListener('click',exportPDF);document.querySelector('#export-png').addEventListener('click',exportPNG)}
 const slot=document.querySelector('#chart-slot');slot.innerHTML='';destroyCharts();if(result.chart){slot.innerHTML=`<div class="panel chart-panel"><div class="panel-heading"><h2>Visualização gráfica</h2><span>${icon('chart-no-axes-combined')}</span></div><div class="chart-wrap" id="tool-chart"></div></div>`;requestAnimationFrame(()=>drawChart('#tool-chart',result.chart))}
}
function calcButtons(scientific){const basic=[['x²','secondary'],['√','secondary'],['log','secondary'],['!','secondary'],['MC','secondary'],['MR','secondary'],['M+','secondary'],['M−','secondary'],['AC','danger'],['(','secondary'],[')','secondary'],['÷','operator'],['7',''],['8',''],['9',''],['×','operator'],['4',''],['5',''],['6',''],['−','operator'],['1',''],['2',''],['3',''],['+','operator'],['%','operator'],['0',''],['.',''],['=','equals']];const sci=[['sin','secondary'],['cos','secondary'],['tan','secondary'],['π','secondary'],['e','secondary'],['asin','secondary'],['acos','secondary'],['atan','secondary'],['ln','secondary'],['log','secondary'],['√','secondary'],['x²','secondary'],['xʸ','secondary'],['!','secondary'],['⌫','danger'],['MC','secondary'],['MR','secondary'],['M+','secondary'],['M−','secondary'],['AC','danger'],['7',''],['8',''],['9',''],['÷','operator'],['(','secondary'],['4',''],['5',''],['6',''],['×','operator'],[')','secondary'],['1',''],['2',''],['3',''],['−','operator'],['%','operator'],['0',''],['.',''],['=','equals'],['+','operator'],['CE','danger']];return (scientific?sci:basic).map(([text,cls])=>`<button type="button" class="calc-key ${cls}" data-key="${esc(text)}" aria-label="${esc(text)}">${esc(text)}</button>`).join('')}
function renderCalculator(id){const sci=id==='cientifica',s=calcState[id];main.insertAdjacentHTML('beforeend',`<div class="calculator-shell"><section class="panel"><div class="panel-heading"><h2>${sci?'Painel científico':'Calculadora de operações'}</h2><div style="display:flex;align-items:center;gap:8px"><span class="muted" style="font-size:11px">Ângulos</span><div class="segment"><button id="angle-deg" class="${s.degrees?'active':''}" aria-pressed="${s.degrees}">DEG</button><button id="angle-rad" class="${!s.degrees?'active':''}" aria-pressed="${!s.degrees}">RAD</button></div><button type="button" id="calc-copy" class="ghost-button" aria-label="Copiar resultado" title="Copiar resultado">${icon('copy')}</button></div></div><div class="calc-screen"><div class="calc-memory-indicator" id="memory-indicator">${storage.memory()?'M':''}</div><label for="calc-input" style="position:absolute;width:1px;height:1px;overflow:hidden">Expressão matemática</label><input id="calc-input" class="calc-expression" autocomplete="off" inputmode="text" placeholder="Digite uma expressão" value="${esc(s.expression)}" /><div class="calc-display" id="calc-display" aria-live="polite">${esc(s.result)}</div></div><div class="calculator-keypad ${sci?'scientific':''}" id="calculator-keypad">${calcButtons(sci)}</div><p class="helper-note">${icon('info')} Digite uma expressão ou use as teclas. Pressione Enter para calcular.</p></section><aside class="panel calc-history-panel"><div class="panel-heading"><h2>Histórico recente</h2><button class="action-small" id="clear-calc-history">Limpar</button></div><div id="calc-history" class="calc-hist-scroll"></div></aside></div>`);
 const inp=document.querySelector('#calc-input');inp.addEventListener('input',()=>{s.expression=inp.value});inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();calculateExpression(id)}});
 document.querySelector('#calculator-keypad').addEventListener('click',e=>{const btn=e.target.closest('[data-key]');if(!btn)return;const key=btn.dataset.key;const insert=t=>{const a=inp.selectionStart??inp.value.length,b=inp.selectionEnd??a;inp.value=inp.value.slice(0,a)+t+inp.value.slice(b);inp.focus();inp.setSelectionRange(a+t.length,a+t.length);s.expression=inp.value};
 if(key==='AC'){inp.value='';s.expression='';s.result='0'}else if(key==='CE'){inp.value='';s.expression=''}else if(key==='⌫'){const start=inp.selectionStart??inp.value.length;const end=inp.selectionEnd??start;const begin=start===end?Math.max(0,start-1):start;inp.value=inp.value.slice(0,begin)+inp.value.slice(end);s.expression=inp.value;inp.focus();inp.setSelectionRange(begin,begin)}else if(key==='='){calculateExpression(id);return}else if(['MC','MR','M+','M−'].includes(key)){memoryAction(key,id);return}else if(key==='x²')insert('^2');else if(key==='xʸ')insert('^');else if(key==='√')insert('sqrt(');else if(['sin','cos','tan','asin','acos','atan','ln','log'].includes(key))insert(key+'(');else insert({'×':'*','÷':'/','−':'-','π':'pi'}[key]||key);
 document.querySelector('#calc-display').textContent=s.result;
 });
 document.querySelector('#calc-copy').onclick=()=>copyText(s.result);
 document.querySelector('#angle-deg').onclick=()=>{s.degrees=true;syncAngle(s)};document.querySelector('#angle-rad').onclick=()=>{s.degrees=false;syncAngle(s)};
 document.querySelector('#clear-calc-history').onclick=()=>dialog('Limpar histórico?',`<p>Todos os cálculos anteriores serão removidos do histórico geral também.</p><div class="panel-actions"><button class="primary-button" id="confirm-clear">Sim, limpar</button><button class="ghost-button close-dialog">Cancelar</button></div>`);
 updateCalcHistory(id);
}
function syncAngle(s){document.querySelector('#angle-deg').classList.toggle('active',s.degrees);document.querySelector('#angle-rad').classList.toggle('active',!s.degrees);document.querySelector('#angle-deg').setAttribute('aria-pressed',String(s.degrees));document.querySelector('#angle-rad').setAttribute('aria-pressed',String(!s.degrees))}
function calculateExpression(id){const s=calcState[id];try{const original=s.expression.trim();if(!original)return;const value=math.evaluateExpression(original,s.degrees);s.result=fmt(value,10);document.querySelector('#calc-display').textContent=s.result;storage.addHistory({tool:id,summary:original,result:s.result});storage.track(id);updateCalcHistory(id);toast('Cálculo concluído')}catch(err){toast(err.message,'error')}}
function updateCalcHistory(id){const el=document.querySelector('#calc-history');if(!el)return;const records=storage.history().filter(x=>x.tool===id).slice(0,30);el.innerHTML=records.map(h=>`<div class="calc-history-item"><button data-reuse="${esc(h.summary)}" aria-label="Reutilizar ${esc(h.summary)}"><small>${esc(h.summary)}</small><strong>${esc(h.result)}</strong></button>${icon('history')}</div>`).join('')||'<div class="result-empty"><span class="empty-icon">'+icon('history')+'</span><b>Sem cálculos ainda</b><p>As operações aparecerão aqui.</p></div>';el.querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>{const s=calcState[id];s.expression=b.dataset.reuse;document.querySelector('#calc-input').value=s.expression;document.querySelector('#calc-input').focus()})}
function memoryAction(key,id){const s=calcState[id];let m=storage.memory();if(key==='MC')m=0;else if(key==='MR'){const inp=document.querySelector('#calc-input');inp.value+=String(m);s.expression=inp.value;inp.focus();toast('Valor recuperado da memória');return}else{try{const value=math.evaluateExpression(s.expression||String(s.result).replace(/\./g,'').replace(',','.'),s.degrees);m+=(key==='M+'?1:-1)*value;if(!Number.isFinite(m))math.fail('Memória excedeu o limite numérico.')}catch(e){toast(e.message,'error');return}}storage.setMemory(m);document.querySelector('#memory-indicator').textContent=m?'M':'';toast(key==='MC'?'Memória apagada':'Memória atualizada')}
function makeOfflinePDF(rows,title){
 // PDF 1.4 mínimo: sem dependências de rede, fonte Helvetica e paginação A4.
 const pageSize=43,pgCount=Math.ceil(rows.length/pageSize),ids=Array.from({length:pgCount},(_,i)=>4+i*2),objects=[];
 const ascii=s=>String(s).replace(/×/g,'x').replace(/[^\x20-\x7e]/g,'').replace(/[()\\]/g,'\\$&');
 objects[1]='<< /Type /Catalog /Pages 2 0 R >>';
 objects[2]=`<< /Type /Pages /Kids [${ids.map(i=>i+' 0 R').join(' ')}] /Count ${pgCount} >>`;
 objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
 ids.forEach((id,page)=>{
  const current=rows.slice(page*pageSize,(page+1)*pageSize);
  const lines=[`BT /F1 20 Tf 44 793 Td (${ascii(title)}) Tj ET`,`BT /F1 10 Tf 44 766 Td (CalcHub Pro | Pagina ${page+1} de ${pgCount}) Tj ET`,...current.map((r,i)=>`BT /F1 12 Tf 48 ${738-i*16} Td (${ascii(r[0])} = ${ascii(r[1])}) Tj ET`)];
  const stream=lines.join('\n')+'\n';
  objects[id]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${id+1} 0 R >>`;
  objects[id+1]=`<< /Length ${stream.length} >>\nstream\n${stream}endstream`;
 });
 let pdf='%PDF-1.4\n',offsets=[0];
 for(let i=1;i<objects.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}
 const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;
 for(let i=1;i<objects.length;i++)pdf+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;
 pdf+=`trailer\n<< /Root 1 0 R /Size ${objects.length} >>\nstartxref\n${xref}\n%%EOF`;
 return new Blob([pdf],{type:'application/pdf'});
}
function exportPDF(){
 if(!lastResult?.result.rows)return;
 const rows=lastResult.result.rows,filename=`calchub-tabuada-${lastResult.data.numero}.pdf`,{jsPDF}=window.jspdf||{};
 if(jsPDF){const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});let y=21;const addHeader=()=>{pdf.setFont('helvetica','bold');pdf.setFontSize(19);pdf.text('CalcHub Pro | Tabuada',18,16);pdf.setFont('helvetica','normal');pdf.setFontSize(10)};addHeader();rows.forEach(r=>{if(y>280){pdf.addPage();y=22;addHeader()}pdf.text(`${r[0].replace('×','x')} = ${r[1]}`,20,y);y+=8});pdf.save(filename)}
 else{const blob=makeOfflinePDF(rows,'Tabuada - CalcHub Pro');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
 toast('PDF gerado com sucesso!');
}
function exportPNG(){if(!lastResult?.result.rows)return;const rows=lastResult.result.rows,cols=rows.length>40?4:rows.length>15?2:1,per=Math.ceil(rows.length/cols),line=35,width=cols*258+70,height=Math.max(250,per*line+135);const canvas=document.createElement('canvas');canvas.width=width*2;canvas.height=height*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#101525';ctx.fillRect(0,0,width,height);ctx.fillStyle='#a49aff';ctx.font='bold 26px Arial';ctx.fillText('CalcHub Pro',32,47);ctx.fillStyle='#e9efff';ctx.font='bold 17px Arial';ctx.fillText(`Tabuada do ${lastResult.data.numero}`,32,77);ctx.font='15px Arial';rows.forEach((r,i)=>{const c=Math.floor(i/per),lineNo=i%per;ctx.fillStyle=lineNo%2===0?'#1b2235':'#151c2b';ctx.fillRect(22+c*258,97+lineNo*line,248,33);ctx.fillStyle='#ecf0fc';ctx.fillText(`${r[0]} = ${r[1]}`,34+c*258,120+lineNo*line)});canvas.toBlob(blob=>{if(!blob){toast('Falha ao criar imagem.','error');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`calchub-tabuada-${lastResult.data.numero}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Imagem PNG exportada!')},'image/png')}
function setTheme(mode){state.theme=mode;document.documentElement.dataset.theme=mode;storage.setTheme(mode);document.querySelector('#theme-toggle').innerHTML=icon(mode==='dark'?'sun':'moon');document.querySelector('#theme-toggle').setAttribute('aria-label',mode==='dark'?'Ativar tema claro':'Ativar tema escuro');if(lastResult?.result.chart&&document.querySelector('#tool-chart')){destroyCharts();drawChart('#tool-chart',lastResult.result.chart)}}
function showHelp(){dialog('Central de ajuda',`<p><strong>Bem-vindo ao CalcHub Pro.</strong> Você pode abrir qualquer ferramenta, informar seus valores e consultar o resultado acompanhado das fórmulas e dos passos.</p><p><strong>Atalhos:</strong> <kbd>Ctrl</kbd> + <kbd>K</kbd> / <kbd>⌘</kbd> + <kbd>K</kbd> abre a busca global. <kbd>Esc</kbd> fecha as janelas. <kbd>Enter</kbd> calcula na calculadora.</p><p><strong>Favoritos:</strong> selecione a estrela de uma ferramenta. <strong>Histórico:</strong> os resultados ficam salvos no LocalStorage do navegador, sem precisar de conta.</p><p><strong>Exportação:</strong> na tabuada, baixe o arquivo PNG ou PDF; caso o gerador de PDF não esteja acessível, use a opção "Salvar como PDF" do navegador.</p><p><strong>Privacidade:</strong> seus dados de uso ficam neste navegador. Para apagar registros, acesse Histórico.</p>`)}
function showSearch(){const layer=document.querySelector('#search-layer');layer.innerHTML=`<div class="command-backdrop"><section class="command-palette" role="dialog" aria-label="Pesquisa global de ferramentas" aria-modal="true"><div class="command-input">${icon('search')}<input id="command-search" autofocus autocomplete="off" placeholder="Qual ferramenta você procura?" aria-label="Digite o nome da ferramenta" /><button class="icon-button" id="close-command" aria-label="Fechar busca">${icon('x')}</button></div><div class="command-list" id="command-list"></div><div class="command-footer">Navegue com <kbd>↑</kbd> <kbd>↓</kbd> e selecione com <kbd>Enter</kbd> · <kbd>Esc</kbd> para sair</div></section></div>`;
 const input=document.querySelector('#command-search');let currentIndex=0;
 const redraw=()=>{const value=input.value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const list=tools.filter(t=>(t.name+' '+t.cat+' '+t.desc+' '+t.id).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(value)).slice(0,12);document.querySelector('#command-list').innerHTML=list.map((t,i)=>`<button class="command-item" data-nav="${t.id}" data-command-index="${i}">${catIcon(t)}<span>${esc(t.name)}<small>${esc(t.cat)} · ${esc(t.desc)}</small></span><span class="command-arrow">${icon('arrow-right')}</span></button>`).join('')||`<div class="empty-state"><b>Nada encontrado</b><p>Tente outro termo.</p></div>`;currentIndex=0};
 input.addEventListener('input',redraw);input.addEventListener('keydown',e=>{const items=[...document.querySelectorAll('.command-item')];if(e.key==='ArrowDown'){e.preventDefault();currentIndex=(currentIndex+1)%Math.max(1,items.length);items[currentIndex]?.focus()}if(e.key==='Enter'&&items.length){e.preventDefault();const id=items[currentIndex]?.dataset.nav;closeSearch();goto(id)}});document.querySelector('#close-command').onclick=closeSearch;layer.querySelector('.command-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeSearch()});redraw();requestAnimationFrame(()=>input.focus())}
function closeSearch(){document.querySelector('#search-layer').replaceChildren()}
function render(){destroyCharts();lastResult=null;closeSidebar();const r=route();renderSidebar();if(r.page==='home')renderHome(r.cat);else if(r.page==='favorites')renderFavorites();else if(r.page==='history')renderHistory();else if(r.page==='tool')renderTool(r.id);else renderHome();window.scrollTo({top:0,behavior:'instant'})}
function init(){hydrateIcons(document);document.querySelector('#year').textContent=new Date().getFullYear();setTheme(state.theme);
 document.querySelector('#theme-toggle').addEventListener('click',()=>setTheme(state.theme==='dark'?'light':'dark'));
 document.querySelector('#help-trigger').addEventListener('click',showHelp);
 document.querySelector('#profile-button').addEventListener('click',()=>dialog('Sobre o CalcHub Pro','<p><strong>CalcHub Pro 1.0</strong> — central de cálculos com 20 ferramentas, histórico e favoritos locais, temas claro/escuro e visualizações gráficas.</p><p>Os dados inseridos permanecem no dispositivo. Não há cadastro ou envio de dados para um servidor de cálculo.</p>'));
 document.querySelector('#global-search').addEventListener('click',showSearch);
 document.querySelector('#menu-toggle').addEventListener('click',()=>{document.querySelector('#sidebar').classList.add('open');document.querySelector('#overlay').hidden=false});document.querySelector('#overlay').addEventListener('click',closeSidebar);
 document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();const path=nav.dataset.nav;if(document.querySelector('#search-layer').childElementCount)closeSearch();if(path.startsWith('cat:'))filterCategory=path.slice(4);else if(path==='home')filterCategory='Todas';goto(path);if(location.hash===`#tool/${path}`&&route().page==='tool'&&document.querySelector('#main-content h1')?.textContent===byId[path]?.name)closeSidebar();return}
 const fav=e.target.closest('[data-favorite]');if(fav){toggleFavorite(fav.dataset.favorite);return}
 const filter=e.target.closest('[data-filter]');if(filter){filterCategory=filter.dataset.filter;updateCatalog();return}
 if(e.target.closest('.close-dialog')){document.querySelector('#modal-layer').replaceChildren();return}
 if(e.target.closest('#confirm-clear')){storage.clearHistory();document.querySelector('#modal-layer').replaceChildren();toast('Histórico apagado');render();return}
 });
 document.addEventListener('keydown',e=>{const target=e.target,editing=['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch();return}if(e.key==='/'&&!editing&&!e.ctrlKey&&!e.metaKey){e.preventDefault();showSearch();return}if(e.key==='Escape'){closeSearch();document.querySelector('#modal-layer').replaceChildren();closeSidebar()}});
 window.addEventListener('hashchange',render);
 if(!location.hash)history.replaceState(null,'','#home');render();
}
init();
